package cn.zhuatech.contractai; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import java.util.regex.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class ContractAiApiIntegrationTests{@Autowired MockMvc mvc;String token;@BeforeEach void login()throws Exception{String j=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"operator\",\"password\":\"Demo@2026\"}")).andReturn().getResponse().getContentAsString();Matcher m=Pattern.compile("\\\"token\\\":\\\"([^\\\"]+)\\\"").matcher(j);if(!m.find())throw new AssertionError();token=m.group(1);}@Test void analyzes()throws Exception{mvc.perform(post("/api/ai/contract/analyze").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"contractNo\":\"CT-88\",\"counterparty\":\"客户\",\"contractAmount\":2200000,\"missingRequiredClauses\":2,\"unlimitedLiability\":true,\"autoRenewal\":true,\"nonStandardPaymentTerm\":true,\"expiryDate\":\"2026-09-01\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.riskLevel").value("CRITICAL"));}}
